// Shared HTML shell for crawlable pages: static editorial pages (generated by
// scripts/build-seo-pages.mjs into public/) and Worker-rendered archive pages.
// One template keeps canonical, hreflang, Open Graph and JSON-LD consistent.

export const SITE_ORIGIN = 'https://air-alert-stat.com';
export const SITE_NAME = 'Air Alert Stat';
export const REPOSITORY_URL = 'https://github.com/sergiiiavt/air-stat';
export const OG_IMAGE = { path: '/og-image.png', width: 1200, height: 630 };
export const KYIV_TIME_ZONE = 'Europe/Kyiv';

export const LANGS = ['uk', 'en'];

const CHROME = {
  uk: {
    locale: 'uk_UA',
    home: 'Головна',
    navLabel: 'Розділи сайту',
    breadcrumbLabel: 'Ви тут',
    switchLabel: 'English',
    switchTitle: 'Read this page in English',
    ogAlt: 'Air Alert Stat — статистика повітряних тривог Києва та Київської області',
    footer: 'Історична аналітика, не оперативне оповіщення. Дані можуть бути неповними; під час тривоги дійте за офіційними сигналами.',
    footerLinks: 'Корисні сторінки',
    nav: [
      ['Дашборд', '/'],
      ['Київ', '/kyiv-air-alerts'],
      ['Область', '/kyiv-oblast-alerts'],
      ['Архів по місяцях', '/stats/kyiv'],
      ['Відкриті дані', '/open-data'],
      ['Методологія', '/methodology'],
    ],
  },
  en: {
    locale: 'en_US',
    home: 'Home',
    navLabel: 'Site sections',
    breadcrumbLabel: 'You are here',
    switchLabel: 'Українською',
    switchTitle: 'Читати цю сторінку українською',
    ogAlt: 'Air Alert Stat — air raid alert statistics for Kyiv and Kyiv Oblast',
    footer: 'Historical analytics, not a live warning service. Data can be incomplete; during an alert follow official signals.',
    footerLinks: 'Useful pages',
    nav: [
      ['Dashboard', '/?lang=en'],
      ['Kyiv', '/en/kyiv-air-alerts'],
      ['Kyiv Oblast', '/en/kyiv-oblast-alerts'],
      ['Monthly archive', '/en/stats/kyiv'],
      ['Open data', '/en/open-data'],
      ['Methodology', '/en/methodology'],
    ],
  },
};

export function chrome(lang) {
  return CHROME[lang] ?? CHROME.uk;
}

export function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function absoluteUrl(path) {
  return new URL(path, SITE_ORIGIN).toString();
}

/** JSON for <script type="application/ld+json">; "<" is escaped so content cannot close the tag. */
export function jsonLdScript(data) {
  return `<script type="application/ld+json">${JSON.stringify(data).replace(/</g, '\\u003c')}</script>`;
}

export const ORGANIZATION = {
  '@type': 'Organization',
  '@id': `${SITE_ORIGIN}/#organization`,
  name: SITE_NAME,
  url: `${SITE_ORIGIN}/`,
  logo: `${SITE_ORIGIN}/icon-512.png`,
  sameAs: [REPOSITORY_URL],
};

export const WEBSITE = {
  '@type': 'WebSite',
  '@id': `${SITE_ORIGIN}/#website`,
  name: SITE_NAME,
  url: `${SITE_ORIGIN}/`,
  inLanguage: ['uk', 'en'],
  publisher: { '@id': `${SITE_ORIGIN}/#organization` },
};

export function breadcrumbJsonLd(items) {
  return {
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

/**
 * page: {
 *   lang, path, alternates: { uk, en }, title, description, h1?, ogType?,
 *   breadcrumbs: [{ name, path }], main (HTML), jsonLd: [objects],
 *   robots?, dateModified?
 * }
 */
export function renderDocument(page) {
  const t = chrome(page.lang);
  const canonical = absoluteUrl(page.path);
  const alternates = page.alternates ?? {};
  const robots = page.robots ?? 'index,follow,max-image-preview:large';
  const otherLang = page.lang === 'uk' ? 'en' : 'uk';
  const switchPath = alternates[otherLang];
  const pageNode = {
    '@type': page.schemaType ?? 'WebPage',
    '@id': `${canonical}#webpage`,
    name: page.h1 ?? page.title,
    description: page.description,
    url: canonical,
    inLanguage: page.lang,
    isPartOf: { '@id': `${SITE_ORIGIN}/#website` },
    ...(page.dateModified ? { dateModified: page.dateModified } : {}),
    ...(page.about ? { about: page.about } : {}),
  };
  const graph = [ORGANIZATION, WEBSITE, pageNode];
  if (page.breadcrumbs?.length) graph.push(breadcrumbJsonLd(page.breadcrumbs));
  for (const extra of page.jsonLd ?? []) graph.push(extra);

  const hreflang = [];
  for (const lang of LANGS) {
    if (alternates[lang]) hreflang.push(`<link rel="alternate" hreflang="${lang}" href="${esc(absoluteUrl(alternates[lang]))}" />`);
  }
  if (alternates.uk) hreflang.push(`<link rel="alternate" hreflang="x-default" href="${esc(absoluteUrl(alternates.uk))}" />`);

  const breadcrumbs = page.breadcrumbs?.length
    ? `<nav class="context" aria-label="${esc(t.breadcrumbLabel)}">${page.breadcrumbs
        .map((item, index) =>
          index === page.breadcrumbs.length - 1
            ? `<span aria-current="page">${esc(item.name)}</span>`
            : `<a href="${esc(item.path)}">${esc(item.name)}</a>`)
        .join(' / ')}</nav>`
    : '';

  const nav = t.nav.map(([label, href]) => `<a href="${esc(href)}">${esc(label)}</a>`).join('');
  const switchLink = switchPath
    ? `<a class="lang-switch" href="${esc(switchPath)}" hreflang="${otherLang}" lang="${otherLang}" title="${esc(t.switchTitle)}">${esc(t.switchLabel)}</a>`
    : '';

  return `<!doctype html>
<html lang="${page.lang}">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>${esc(page.title)}</title>
<meta name="description" content="${esc(page.description)}" />
<meta name="robots" content="${esc(robots)}" />
${page.noCanonical ? '' : `<link rel="canonical" href="${esc(canonical)}" />`}
${hreflang.join('\n')}
<link rel="icon" type="image/svg+xml" href="/favicon.svg" />
<link rel="stylesheet" href="/seo.css" />
<meta name="theme-color" content="#15191d" />
<meta property="og:type" content="${esc(page.ogType ?? 'article')}" />
<meta property="og:site_name" content="${SITE_NAME}" />
<meta property="og:locale" content="${t.locale}" />
${page.noCanonical ? '' : `<meta property="og:url" content="${esc(canonical)}" />`}
<meta property="og:title" content="${esc(page.title)}" />
<meta property="og:description" content="${esc(page.description)}" />
<meta property="og:image" content="${absoluteUrl(OG_IMAGE.path)}" />
<meta property="og:image:width" content="${OG_IMAGE.width}" />
<meta property="og:image:height" content="${OG_IMAGE.height}" />
<meta property="og:image:alt" content="${esc(t.ogAlt)}" />
<meta name="twitter:card" content="summary_large_image" />
${jsonLdScript({ '@context': 'https://schema.org', '@graph': graph })}
</head>
<body>
<header><div class="wrap"><a class="brand" href="${page.lang === 'en' ? '/?lang=en' : '/'}">${SITE_NAME}</a><nav aria-label="${esc(t.navLabel)}">${nav}${switchLink}</nav></div></header>
<main>
${breadcrumbs}
${page.main}
</main>
<footer><p>${esc(t.footer)}</p><p><a href="${esc(t.nav[3][1])}">${esc(t.nav[3][0])}</a> · <a href="${esc(t.nav[4][1])}">${esc(t.nav[4][0])}</a> · <a href="${esc(t.nav[5][1])}">${esc(t.nav[5][0])}</a> · <a href="${REPOSITORY_URL}">GitHub</a></p></footer>
</body>
</html>
`;
}

// ---------------------------------------------------------------------------
// Formatting (Europe/Kyiv calendar, Ukrainian and English wording)

const MONTHS = {
  uk: {
    nominative: ['січень', 'лютий', 'березень', 'квітень', 'травень', 'червень', 'липень', 'серпень', 'вересень', 'жовтень', 'листопад', 'грудень'],
    locative: ['січні', 'лютому', 'березні', 'квітні', 'травні', 'червні', 'липні', 'серпні', 'вересні', 'жовтні', 'листопаді', 'грудні'],
    genitive: ['січня', 'лютого', 'березня', 'квітня', 'травня', 'червня', 'липня', 'серпня', 'вересня', 'жовтня', 'листопада', 'грудня'],
  },
  en: {
    nominative: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
  },
};

export function monthName(month, lang, form = 'nominative') {
  const index = Number(month.slice(5, 7)) - 1;
  if (lang === 'en') return MONTHS.en.nominative[index];
  return MONTHS.uk[form][index];
}

export function capitalize(value) {
  return value ? value[0].toUpperCase() + value.slice(1) : value;
}

/** "жовтень 2026" / "October 2026" */
export function monthLabel(month, lang) {
  return `${monthName(month, lang)} ${month.slice(0, 4)}`;
}

/** "у жовтні 2026 року" / "in October 2026" */
export function inMonth(month, lang) {
  return lang === 'en'
    ? `in ${monthName(month, 'en')} ${month.slice(0, 4)}`
    : `у ${monthName(month, 'uk', 'locative')} ${month.slice(0, 4)} року`;
}

/** "3 жовтня 2026" / "3 October 2026" */
export function formatDate(date, lang, { year = true } = {}) {
  const [y, m, d] = date.split('-').map(Number);
  if (lang === 'en') return `${d} ${MONTHS.en.nominative[m - 1]}${year ? ` ${y}` : ''}`;
  return `${d} ${MONTHS.uk.genitive[m - 1]}${year ? ` ${y}` : ''}`;
}

const timeFormat = new Intl.DateTimeFormat('en-GB', {
  timeZone: KYIV_TIME_ZONE, hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
});
const dateFormat = new Intl.DateTimeFormat('en-CA', {
  timeZone: KYIV_TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit',
});

export function kyivTime(iso) {
  return timeFormat.format(new Date(iso));
}

export function kyivDateOf(iso) {
  return dateFormat.format(new Date(iso));
}

/** "23 листопада 2026, 22:40" */
export function formatDateTime(iso, lang) {
  return `${formatDate(kyivDateOf(iso), lang)}, ${kyivTime(iso)}`;
}

export function formatNumber(value, lang) {
  return new Intl.NumberFormat(lang === 'en' ? 'en-US' : 'uk-UA', { maximumFractionDigits: 0 }).format(value);
}

export function formatPercent(ratio, lang) {
  return new Intl.NumberFormat(lang === 'en' ? 'en-US' : 'uk-UA', {
    style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 1,
  }).format(ratio);
}

/** "196 год 30 хв" / "196 h 30 min"; seconds are rounded to whole minutes. */
export function formatDuration(seconds, lang) {
  const totalMinutes = Math.round(Math.max(0, seconds) / 60);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  const h = lang === 'en' ? 'h' : 'год';
  const m = lang === 'en' ? 'min' : 'хв';
  if (hours === 0) return `${minutes} ${m}`;
  if (minutes === 0) return `${formatNumber(hours, lang)} ${h}`;
  return `${formatNumber(hours, lang)} ${h} ${minutes} ${m}`;
}

/** Ukrainian plural form: 1 тривога, 2 тривоги, 5 тривог. */
export function pluralUk(n, one, few, many) {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return one;
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return few;
  return many;
}

export function alertsPhrase(n, lang) {
  if (lang === 'en') return `${formatNumber(n, lang)} air raid alert${n === 1 ? '' : 's'}`;
  // Accusative after "зафіксовано": 1 повітряну тривогу, 2 повітряні тривоги, 5 повітряних тривог.
  return `${formatNumber(n, lang)} ${pluralUk(n, 'повітряну тривогу', 'повітряні тривоги', 'повітряних тривог')}`;
}

export function daysPhrase(n, lang) {
  if (lang === 'en') return `${formatNumber(n, lang)} day${n === 1 ? '' : 's'}`;
  return `${formatNumber(n, lang)} ${pluralUk(n, 'день', 'дні', 'днів')}`;
}

// ---------------------------------------------------------------------------
// Accessible inline SVG bar chart; the page always also carries a data table.

export function barChartSvg({ values, labels, ticks = labels, title, valueLabel, highlightLast = false, tickEvery = 1 }) {
  const width = 760;
  const height = 220;
  const left = 34;
  const bottom = 24;
  const top = 10;
  const plotHeight = height - top - bottom;
  const gridLines = 4;
  // Round the axis to 1/2/2.5/5 x 10^n steps so tick labels stay readable.
  const rawStep = Math.max(...values, 0.0001) / gridLines;
  const magnitude = 10 ** Math.floor(Math.log10(rawStep));
  const gridStep = [1, 2, 2.5, 5, 10].map((f) => f * magnitude).find((v) => v >= rawStep) ?? 10 * magnitude;
  const max = gridStep * gridLines;
  const step = (width - left - 4) / Math.max(1, values.length);
  const barWidth = Math.max(2, step * 0.72);
  const parts = [];
  for (let i = 0; i <= gridLines; i++) {
    const y = top + plotHeight - (plotHeight * i) / gridLines;
    const value = gridStep * i;
    const label = Number.isInteger(value) ? String(value) : value.toFixed(gridStep < 0.1 ? 2 : 1);
    parts.push(`<line x1="${left}" x2="${width}" y1="${y.toFixed(1)}" y2="${y.toFixed(1)}" class="grid" />`);
    parts.push(`<text x="${left - 4}" y="${(y + 4).toFixed(1)}" text-anchor="end" class="axis">${label}</text>`);
  }
  values.forEach((value, index) => {
    const h = (plotHeight * value) / max;
    const x = left + index * step + (step - barWidth) / 2;
    const y = top + plotHeight - h;
    const cls = highlightLast && index === values.length - 1 ? 'bar bar--current' : 'bar';
    parts.push(`<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barWidth.toFixed(1)}" height="${Math.max(0, h).toFixed(1)}" class="${cls}"><title>${esc(labels[index])}: ${esc(valueLabel(value))}</title></rect>`);
    if (index % tickEvery === 0) {
      parts.push(`<text x="${(x + barWidth / 2).toFixed(1)}" y="${height - 6}" text-anchor="middle" class="axis">${esc(ticks[index])}</text>`);
    }
  });
  return `<figure class="chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(title)}" preserveAspectRatio="none"><title>${esc(title)}</title>${parts.join('')}</svg><figcaption>${esc(title)}</figcaption></figure>`;
}
